 23 | static void hex_color(const char* hex, float* r, float* g, float* b) {
 24 |   unsigned int rv = 240, gv = 240, bv = 240;
 25 |   if (hex && hex[0] == '#' && strlen(hex) >= 7) sscanf(hex + 1, "%02x%02x%02x", &rv, &gv, &bv);
 26 |   *r = (float)rv / 255.0f; *g = (float)gv / 255.0f; *b = (float)bv / 255.0f;
