 39 | void awts_font_init(AwtsBrowserState* state, HDC dc) {
 40 |   if (state->font.ready) return;
 41 |   state->font.base = glGenLists(256);
 42 |   state->font.font = CreateFontA(-18, 0, 0, 0, FW_NORMAL, FALSE, FALSE, FALSE, ANSI_CHARSET, OUT_TT_PRECIS, CLIP_DEFAULT_PRECIS, ANTIALIASED_QUALITY, FF_DONTCARE | VARIABLE_PITCH, "Times New Roman");
 43 |   if (!state->font.font) state->font.font = CreateFontA(-17, 0, 0, 0, FW_NORMAL, FALSE, FALSE, FALSE, ANSI_CHARSET, OUT_TT_PRECIS, CLIP_DEFAULT_PRECIS, ANTIALIASED_QUALITY, FF_DONTCARE | VARIABLE_PITCH, "Segoe UI");
 44 |   SelectObject(dc, state->font.font);
 45 |   state->font.ready = wglUseFontBitmapsA(dc, 0, 255, state->font.base) ? 1 : 0;
