 60 | void awts_draw_text(AwtsBrowserState* state, float x, float y, const char* text, float r, float g, float b) {
 61 |   if (!state->font.ready || !text) return;
 62 |   glColor3f(r, g, b);
 63 |   glRasterPos2f(x, y);
 64 |   glPushAttrib(GL_LIST_BIT);
 65 |   glListBase(state->font.base);
 66 |   glCallLists((GLsizei)strlen(text), GL_UNSIGNED_BYTE, text);
