139 | static int draw_executor_stream(AwtsBrowserState* state) {
140 |   const char* stream = AWTS_NATIVE_RENDER_STREAM;
141 |   if (!stream || !*stream) return 0;
142 |   char* copy = _strdup(stream);
143 |   if (!copy) return 0;
144 |   float ox = sx(state, 96), oy = sy(state, 150);
145 |   float scaleX = sw(state, 2), scaleY = -sh(state, 2);
146 |   for (char* line = copy; line && *line;) {
147 |     char* next = strchr(line, '\n');
148 |     if (next) *next++ = 0;
149 |     char kind[16], id[16], a[64], b[64], c[160], d[64], e[64];
150 |     char* at = line;
151 |     memset(kind, 0, sizeof(kind)); memset(id, 0, sizeof(id));
152 |     memset(a, 0, sizeof(a)); memset(b, 0, sizeof(b)); memset(c, 0, sizeof(c));
153 |     memset(d, 0, sizeof(d)); memset(e, 0, sizeof(e));
154 |     next_part(&at, kind, sizeof(kind)); next_part(&at, id, sizeof(id));
155 |     next_part(&at, a, sizeof(a)); next_part(&at, b, sizeof(b));
156 |     next_part(&at, c, sizeof(c)); next_part(&at, d, sizeof(d)); next_part(&at, e, sizeof(e));
157 |     if (!strcmp(kind, "BOX")) {
158 |       float r, g, blue; hex_color(e, &r, &g, &blue);
159 |       rect(ox + atof(a) * scaleX, oy + atof(b) * scaleY, atof(c) * scaleX, atof(d) * scaleY, r, g, blue);
160 |       outline(ox + atof(a) * scaleX, oy + atof(b) * scaleY, atof(c) * scaleX, atof(d) * scaleY, 0.70f, 0.72f, 0.78f);
161 |     } else if (!strcmp(kind, "TEXT")) {
162 |       float r, g, blue; hex_color(d, &r, &g, &blue);
163 |       awts_draw_text(state, ox + atof(a) * scaleX, oy + atof(b) * scaleY, c, r, g, blue);
164 |     } else if (!strcmp(kind, "WEBGL")) {
165 |       rect(sx(state, 470), sy(state, 180 + atoi(id) * 18), sw(state, 220), -sh(state, 10), 0.10f, 0.18f, 0.32f);
166 |     }
167 |     line = next;
168 |   }
169 |   free(copy);
170 |   return 1;
171 | }
